// Generated by vibelang from src/session/list.ts; the migrate flow writes it again with each batch.
export async function listAllSessions(api, input) {
    const load = async (cursor) => {
        const result = await api.list({ ...input, limit: input.limit ?? 100, cursor });
        const sessions = result.data;
        if (result.data.length === 0 || !result.cursor.next)
            return sessions;
        return [...sessions, ...(await load(result.cursor.next))];
    };
    return load();
}
